function hmac(key, str) {
  return crypto.createHmac('sha256', key).update(str).digest();
}

function hash(str) {
  return crypto.createHash('sha256').update(str).digest('hex');
}

async function listObjects(prefix = '') {
  const method = 'GET';
  const now = new Date();
  const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, '');
  const dateStamp = amzDate.slice(0, 8);
  const service = 's3';
  const region = 'auto';

  const canonicalUri = `/${bucket}`;
  const queryParams = new URLSearchParams({
    'list-type': '2',
    'max-keys': '50',
  });
  if (prefix) queryParams.set('prefix', prefix);
  queryParams.sort();
  const canonicalQueryString = queryParams.toString();

  const payloadHash = hash('');
  const canonicalHeaders = `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${amzDate}\n`;
  const signedHeaders = 'host;x-amz-content-sha256;x-amz-date';

  const canonicalRequest = `${method}\n${canonicalUri}\n${canonicalQueryString}\n${canonicalHeaders}\n${signedHeaders}\n${payloadHash}`;

  const algorithm = 'AWS4-HMAC-SHA256';
  const credentialScope = `${dateStamp}/${region}/${service}/aws4_request`;
  const stringToSign = `${algorithm}\n${amzDate}\n${credentialScope}\n${hash(canonicalRequest)}`;

  const kDate = hmac('AWS4' + secretKey, dateStamp);
  const kRegion = hmac(kDate, region);
  const kService = hmac(kRegion, service);
  const kSigning = hmac(kService, 'aws4_request');
  const signature = crypto.createHmac('sha256', kSigning).update(stringToSign).digest('hex');

  const authHeader = `${algorithm} Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  const url = `${endpoint}${canonicalUri}?${canonicalQueryString}`;
  const res = await fetch(url, {
    method,
    headers: {
      'x-amz-date': amzDate,
      'x-amz-content-sha256': payloadHash,
      'Authorization': authHeader,
    },
  });

  const text = await res.text();
  console.log('Status:', res.status);
  console.log('Response:\n', text);
}

