/**
 * Standard Types & Interfaces for UTH Scientific Literature RAG System
 * Conforms to docs/RAG.md and docs/prompt.md (Feature F1)
 */

export type SectionType =
  | 'abstract'
  | 'introduction'
  | 'method'
  | 'experiment'
  | 'discussion'
  | 'other';

/**
 * 1. ScientificChunk: Represents a single record row in LanceDB table `scientific_papers_gold`.
 */
export interface ScientificChunk {
  chunk_id: string;
  paper_id: string;
  title: string;
  authors: string[];
  primary_category: string;
  section_title: string;
  section_type: SectionType | string;
  text: string;
  context_text: string;
  word_count: number;
  vector?: number[];
  _distance?: number;
}

/**
 * 2. PaperSection: Structure of a parsed section within full-text paper metadata.
 */
export interface PaperSection {
  section_id: string;
  section_title: string;
  section_type: SectionType | string;
  content: string;
  paragraphs: string[];
}

/**
 * 3. ScientificPaperSilver: Full paper metadata from Silver parquet lakehouse tier.
 */
export interface ScientificPaperSilver {
  paper_id: string;
  abstract_hash: string;
  doi: string | null;
  journal_ref: string | null;
  title: string;
  abstract: string;
  authors: string[];
  categories: string[];
  primary_category: string;
  published_date: string;
  crawled_at: string;
  pdf_url: string;
  html_url: string;
  total_sections: number;
  total_math_count: number;
  total_words: number;
  sections_json: string | PaperSection[];
  clean_full_text: string;
  transformed_at: string;
  cite_count: number;
  year: number;
}

/**
 * 4. GraphInfluencer: Influencer node structure from graph_coauthorship.json PageRank.
 */
export interface GraphInfluencer {
  author: string;
  pagerank: number;
  degree?: number;
}

/**
 * 5. AssociationRule: FP-Growth frequent itemset rule structure from association_rules.json.
 */
export interface AssociationRule {
  antecedents: string[];
  consequents: string[];
  support: number;
  confidence: number;
  lift: number;
}

/**
 * 6. RAGSearchRequest: Search query input parameters for retrieval & generation.
 */
export interface RAGSearchRequest {
  query: string;
  top_k?: number;
  category?: string;
  use_authority_boost?: boolean;
  expand_query?: boolean;
}

/**
 * 7. GroundedChunkResult: Candidate chunk scored by vector similarity and graph authority boost.
 */
export interface GroundedChunkResult {
  chunk_id: string;
  paper_id: string;
  title: string;
  authors: string[];
  section_title: string;
  text: string;
  similarity_score: number;
  authority_score?: number;
  final_score: number;
  citation_tag: `[Paper: ${string}]` | string;
}

/**
 * 8. RAGSynthesisResponse: Complete response returned by RAG pipeline.
 */
export interface RAGSynthesisResponse {
  query: string;
  answer: string;
  citations: string[];
  grounded_chunks: GroundedChunkResult[];
  latency_ms: number;
}

import { execSync } from 'child_process';
import * as os from 'os';
import { Logger } from '@nestjs/common';

export interface GpuInfo {
  hasGpu: boolean;
  type: 'cuda' | 'metal' | 'vulkan' | 'cpu';
  platform: string;
  arch: string;
  details: string;
  nodeLlamaGpuOption: 'auto' | 'cuda' | 'metal' | 'vulkan' | false;
}

const logger = new Logger('GpuDetector');

/**
 * Detect GPU capabilities across Windows (NVIDIA CUDA), macOS (Apple Silicon Metal/MPS), and Linux.
 */
export function detectGpu(): GpuInfo {
  const platform = os.platform();
  const arch = os.arch();

  // 1. Apple Silicon (macOS Metal / MPS)
  if (platform === 'darwin') {
    if (arch === 'arm64') {
      logger.log('Detected Apple Silicon (M-series). Enabling Metal GPU acceleration.');
      return {
        hasGpu: true,
        type: 'metal',
        platform,
        arch,
        details: 'Apple Silicon Metal/MPS GPU Acceleration',
        nodeLlamaGpuOption: 'metal',
      };
    } else {
      logger.log('Detected Intel Mac. Checking for external GPU or fallback to CPU.');
      return {
        hasGpu: false,
        type: 'cpu',
        platform,
        arch,
        details: 'Intel Mac - CPU fallback',
        nodeLlamaGpuOption: 'auto',
      };
    }
  }

  // 2. Windows or Linux: Check for NVIDIA CUDA
  if (platform === 'win32' || platform === 'linux') {
    try {
      const output = execSync('nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader', {
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'ignore'],
        timeout: 3000,
      }).trim();

      if (output && output.length > 0) {
        logger.log(`Detected NVIDIA GPU via nvidia-smi: ${output}. Enabling CUDA.`);
        return {
          hasGpu: true,
          type: 'cuda',
          platform,
          arch,
          details: `NVIDIA CUDA (${output})`,
          nodeLlamaGpuOption: 'cuda',
        };
      }
    } catch {
      // nvidia-smi failed or not installed
    }
  }

  // 3. Fallback: let node-llama-cpp try auto-detection or CPU
  logger.warn('No dedicated NVIDIA CUDA or Apple Metal GPU detected. Defaulting to auto/CPU.');
  return {
    hasGpu: false,
    type: 'cpu',
    platform,
    arch,
    details: 'CPU Only (No dedicated CUDA/Metal detected)',
    nodeLlamaGpuOption: 'auto',
  };
}

import { detectGpu } from './gpu.util';

describe('GpuUtil', () => {
  it('should detect GPU capabilities without throwing', () => {
    const gpuInfo = detectGpu();
    expect(gpuInfo).toBeDefined();
    expect(typeof gpuInfo.hasGpu).toBe('boolean');
    expect(['cuda', 'metal', 'vulkan', 'cpu']).toContain(gpuInfo.type);
    expect(gpuInfo.details).toBeTruthy();
    expect(gpuInfo.platform).toBeTruthy();
  });
});

import { Injectable, OnModuleInit, BadRequestException, Logger } from '@nestjs/common';
import { pipeline, FeatureExtractionPipeline } from '@xenova/transformers';

@Injectable()
export class EmbeddingService implements OnModuleInit {
  private readonly logger = new Logger(EmbeddingService.name);
  private embedder: FeatureExtractionPipeline | null = null;
  private readonly modelName = 'Xenova/nomic-embed-text-v1.5';
  private readonly expectedDimension = 768;

  async onModuleInit(): Promise<void> {
    try {
      this.logger.log(`Initializing embedding pipeline with model: ${this.modelName}...`);
      this.embedder = await pipeline('feature-extraction', this.modelName);
      this.logger.log(`Embedding model ${this.modelName} loaded successfully.`);
    } catch (error) {
      this.logger.error(`Failed to load embedding pipeline: ${(error as Error).message}`, (error as Error).stack);
      throw error;
    }
  }

  /**
   * Generates a 768-D normalized embedding vector for the user query.
   * Enforces Nomic v1.5 asymmetric prefix `search_query: `.
   */
  async generateEmbedding(query: string): Promise<number[]> {
    if (!query || query.trim() === '') {
      throw new BadRequestException('Query cannot be empty');
    }

    if (!this.embedder) {
      this.logger.warn('Embedder was not initialized; initializing on demand...');
      await this.onModuleInit();
    }

    const formattedText = `search_query: ${query.trim()}`;

    try {
      const output = await this.embedder!(formattedText, {
        pooling: 'mean',
        normalize: true,
      });

      const vector = Array.from(output.data as Float32Array | number[]) as number[];

      if (vector.length !== this.expectedDimension) {
        throw new Error(
          `Unexpected embedding dimension: got ${vector.length}, expected ${this.expectedDimension}`,
        );
      }

      return vector;
    } catch (error) {
      this.logger.error(`Error generating embedding for query: "${query}": ${(error as Error).message}`);
      throw error;
    }
  }
}

