import { VectorStoreModule } from '../vector-store/vector-store.module';
import { MiningModule } from '../mining/mining.module';
import { LlmModule } from '../llm/llm.module';

@Module({
  imports: [EmbeddingModule, VectorStoreModule, MiningModule, LlmModule],
  controllers: [RagController],
  providers: [RagService],
  exports: [RagService],
})
export class RagModule {}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { RagModule } from './rag/rag.module';

@Module({
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
      envFilePath: ['.env', '../.env'],
    }),
    RagModule,
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe, Logger } from '@nestjs/common';
import { AppModule } from './app.module';

async function bootstrap() {
  const logger = new Logger('Bootstrap');
  const app = await NestFactory.create(AppModule);

  // Global DTO Validation
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );

  // CORS for frontend
  const frontendOrigin = process.env.FRONTEND_ORIGIN || 'http://localhost:5173';
  app.enableCors({
    origin: [frontendOrigin, 'http://localhost:3000', 'http://127.0.0.1:5173'],
    methods: 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
    credentials: true,
  });

  const port = process.env.GATEWAY_PORT || process.env.PORT || 8000;
  await app.listen(port);
  logger.log(`Scientific RAG Backend server listening on port ${port}`);
  logger.log(`Health endpoint: http://localhost:${port}/api/rag/health`);
  logger.log(`Chat endpoint: http://localhost:${port}/api/rag/chat`);
}
bootstrap();

import * as fs from 'fs';
import * as path from 'path';
import { pipeline } from 'stream/promises';
import { Readable } from 'stream';

const MODEL_URL =
  'https://huggingface.co/Qwen/Qwen2.5-7B-Instruct-GGUF/resolve/main/qwen2.5-7b-instruct-q4_k_m.gguf?download=true';

const TARGET_DIR = path.resolve(
  process.cwd(),
  '../models/qwen2.5-7b-instruct-q4_k_m',
);
const TARGET_FILE = path.join(
  TARGET_DIR,
  'qwen2.5-7b-instruct-q4_k_m.gguf',
);

async function downloadModel() {
  if (fs.existsSync(TARGET_FILE)) {
    const stats = fs.statSync(TARGET_FILE);
    console.log(
      `Model already exists at: ${TARGET_FILE} (${(stats.size / 1024 / 1024 / 1024).toFixed(2)} GB)`,
    );
    return;
  }

  console.log(`Target directory: ${TARGET_DIR}`);
  fs.mkdirSync(TARGET_DIR, { recursive: true });

  console.log(`Downloading Qwen2.5-7B GGUF model from Hugging Face...`);
  console.log(`URL: ${MODEL_URL}`);

  const res = await fetch(MODEL_URL);
  if (!res.ok || !res.body) {
    throw new Error(`Failed to download model: ${res.status} ${res.statusText}`);
  }

  const totalLength = Number(res.headers.get('content-length') || 0);
  let downloaded = 0;
  let lastLogged = 0;

  const reader = res.body.getReader();
  const fileStream = fs.createWriteStream(TARGET_FILE);

  const readable = new Readable({
    async read() {
      const { done, value } = await reader.read();
      if (done) {
        this.push(null);
      } else {
        downloaded += value.length;
        if (totalLength > 0 && downloaded - lastLogged > 50 * 1024 * 1024) {
          lastLogged = downloaded;
          const pct = ((downloaded / totalLength) * 100).toFixed(1);
          console.log(
            `Progress: ${pct}% (${(downloaded / 1024 / 1024).toFixed(1)} / ${(totalLength / 1024 / 1024).toFixed(1)} MB)`,
          );
        }
        this.push(Buffer.from(value));
      }
    },
  });

  await pipeline(readable, fileStream);
  console.log(`Download completed successfully: ${TARGET_FILE}`);
}

downloadModel().catch((err) => {
  console.error('Error downloading model:', err);
  process.exit(1);
});

import * as fs from 'fs';
import * as path from 'path';

const R2_PUBLIC_URL =
  process.env.R2_PUBLIC_URL ||
  'https://pub-5737c359e0b24ed9ae7fcae02ee90a69.r2.dev';

const TARGET_DIR = path.resolve(process.cwd(), '../data/gold/mining');

const FILES = [
  'graph_coauthorship.json',
  'association_rules.json',
  'clusters.json',
  'eda_summary.json',
  'mining_manifest.json',
  'trends_anomalies.json',
];

async function syncMiningArtifacts() {
  fs.mkdirSync(TARGET_DIR, { recursive: true });
  console.log(`Syncing mining artifacts from R2 (${R2_PUBLIC_URL}) to: ${TARGET_DIR}`);

  for (const file of FILES) {
    const targetFile = path.join(TARGET_DIR, file);
    if (fs.existsSync(targetFile)) {
      console.log(`- ${file} already exists locally.`);
      continue;
    }

    const fileUrl = `${R2_PUBLIC_URL.replace(/\/$/, '')}/gold/mining/${file}`;
    console.log(`- Fetching ${file} from ${fileUrl}...`);
    try {
      const res = await fetch(fileUrl);
      if (!res.ok) {
        console.warn(`  Failed to fetch ${file}: ${res.status}`);
        continue;
      }
      const data = await res.arrayBuffer();
      fs.writeFileSync(targetFile, Buffer.from(data));
      console.log(`  Saved ${file} (${(data.byteLength / 1024).toFixed(1)} KB)`);
    } catch (err) {
      console.warn(`  Error fetching ${file}: ${(err as Error).message}`);
    }
  }

  console.log('Mining artifacts sync completed.');
}

syncMiningArtifacts().catch((err) => {
  console.error('Error in sync-r2:', err);
  process.exit(1);
});

