import {
  IsString,
  IsNotEmpty,
  IsOptional,
  IsInt,
  Min,
  Max,
  IsBoolean,
} from 'class-validator';
import { Type } from 'class-transformer';
import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';

export class QueryDto {
  @ApiProperty({
    description: 'The natural language scientific query or research question.',
    example: 'How does LoRA optimize large models?',
  })
  @IsString()
  @IsNotEmpty()
  query!: string;

  @ApiPropertyOptional({
    description: 'Number of top grounded scientific chunks to retrieve and utilize for synthesis.',
    minimum: 1,
    maximum: 20,
    default: 5,
    example: 3,
  })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(20)
  top_k: number = 5;

  @ApiPropertyOptional({
    description: 'Optional category filter based on arXiv taxonomy (e.g., cs.CV, cs.LG, cs.CL, stat.ML).',
    example: 'cs.LG',
  })
  @IsOptional()
  @IsString()
  category?: string;

  @ApiPropertyOptional({
    description: 'Whether to boost chunk ranking using author co-authorship PageRank authority scores (85% similarity, 15% authority).',
    default: true,
    example: true,
  })
  @IsOptional()
  @IsBoolean()
  use_authority_boost: boolean = true;

  @ApiPropertyOptional({
    description: 'Whether to expand the user query using FP-Growth association rules mined from the scientific corpus.',
    default: false,
    example: false,
  })
  @IsOptional()
  @IsBoolean()
  expand_query: boolean = false;
}

import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';

export class GroundedChunkDto {
  @ApiProperty({ description: 'Unique identifier of the text chunk', example: '2106.09685_sec8' })
  chunk_id!: string;

  @ApiProperty({ description: 'arXiv or publication identifier of the source paper', example: '2106.09685' })
  paper_id!: string;

  @ApiProperty({ description: 'Title of the research paper', example: 'LoRA: Low-Rank Adaptation of Large Language Models' })
  title!: string;

  @ApiPropertyOptional({ description: 'List of authors', type: [String], example: ['J. Edward Hu', 'Yelong Shen', 'Phillip Wallis'] })
  authors?: string[];

  @ApiPropertyOptional({ description: 'Primary arXiv research category', example: 'cs.CL' })
  primary_category?: string;

  @ApiPropertyOptional({ description: 'Section title from which the chunk originated', example: '8 Conclusion and Future Work' })
  section_title?: string;

  @ApiProperty({ description: 'Full text content of the chunk' })
  text!: string;

  @ApiProperty({ description: 'Cosine vector similarity score (0.0 to 1.0)', example: 0.5278 })
  similarity_score!: number;

  @ApiProperty({ description: 'PageRank co-authorship authority score (0.0 to 1.0)', example: 0.3059 })
  authority_score!: number;

  @ApiProperty({ description: 'Final blended ranking score', example: 0.4945 })
  final_score!: number;

  @ApiProperty({ description: 'Academic citation tag formatted for prompt grounding', example: '[Paper: 2106.09685]' })
  citation_tag!: string;
}

export class RAGSynthesisResponseDto {
  @ApiProperty({ description: 'Original user input query', example: 'How does LoRA optimize large models?' })
  query!: string;

  @ApiProperty({ description: 'Synthesized grounded answer containing verified [Paper: {paper_id}] citations' })
  answer!: string;

  @ApiProperty({ description: 'Extracted paper IDs cited in the answer', type: [String], example: ['2106.09685'] })
  citations!: string[];

  @ApiProperty({ description: 'List of grounded candidate chunks used for context', type: [GroundedChunkDto] })
  grounded_chunks!: GroundedChunkDto[];

  @ApiProperty({ description: 'Total end-to-end pipeline latency in milliseconds', example: 14185 })
  latency_ms!: number;
}

export class GpuStatusDto {
  @ApiProperty({ description: 'Whether dedicated or integrated hardware acceleration was detected', example: true })
  hasGpu!: boolean;

  @ApiProperty({ description: 'Acceleration backend type', enum: ['cuda', 'metal', 'vulkan', 'cpu'], example: 'cuda' })
  type!: string;

  @ApiProperty({ description: 'Operating system platform', example: 'win32' })
  platform!: string;

  @ApiProperty({ description: 'CPU/GPU hardware architecture', example: 'x64' })
  arch!: string;

  @ApiProperty({ description: 'Human-readable hardware details', example: 'NVIDIA CUDA (NVIDIA GeForce RTX 4060 Laptop GPU, 581.80, 8188 MiB)' })
  details!: string;

  @ApiProperty({ description: 'node-llama-cpp GPU configuration parameter', example: 'cuda' })
  nodeLlamaGpuOption!: string;
}

export class HealthComponentsDto {
  @ApiProperty({ description: 'LanceDB vector store status', example: 'ready' })
  vectorStore!: string;

  @ApiProperty({ description: 'Local LLM inference engine status', example: 'ready' })
  llm!: string;

  @ApiProperty({ description: 'Detailed GPU hardware profiling and status', type: GpuStatusDto })
  gpu!: GpuStatusDto;
}

export class HealthResponseDto {
  @ApiProperty({ description: 'Overall system health indicator', example: 'ok' })
  status!: string;

  @ApiProperty({ description: 'Service identifier name', example: 'scientific-rag-backend' })
  service!: string;

  @ApiProperty({ description: 'ISO 8601 server timestamp', example: '2026-10-14T09:55:47.807Z' })
  timestamp!: string;

  @ApiProperty({ description: 'Detailed component health indicators', type: HealthComponentsDto })
  components!: HealthComponentsDto;
}

import { Controller, Post, Get, Body, HttpCode, HttpStatus, Logger } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBody } from '@nestjs/swagger';
import { RagService } from './rag.service';
import { QueryDto } from './dto/query.dto';
import { RAGSynthesisResponseDto, HealthResponseDto } from './dto/response.dto';
import { RAGSynthesisResponse } from '../types/scientific-rag';
import { VectorStoreService } from '../vector-store/vector-store.service';
import { LlmService } from '../llm/llm.service';

@ApiTags('Scientific RAG')
@Controller('api/rag')
export class RagController {
  private readonly logger = new Logger(RagController.name);

  constructor(
    private readonly ragService: RagService,
    private readonly vectorStoreService: VectorStoreService,
    private readonly llmService: LlmService,
  ) {}

  @Post('chat')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Query Scientific Literature with RAG',
    description:
      'Performs 768-D dense vector search across 913k scientific paper chunks, applies co-authorship PageRank and association-rules hybrid reranking, and synthesizes a grounded answer using local Qwen2.5-7B with strict [Paper: {paper_id}] citations.',
  })
  @ApiBody({ type: QueryDto })
  @ApiResponse({
    status: HttpStatus.OK,
    description: 'Successfully synthesized grounded answer with extracted academic citations and candidate chunks.',
    type: RAGSynthesisResponseDto,
  })
  @ApiResponse({
    status: HttpStatus.BAD_REQUEST,
    description: 'Invalid input payload, missing query, or out-of-range top_k.',
  })
  async chat(@Body() queryDto: QueryDto): Promise<RAGSynthesisResponse> {
    this.logger.log(`Received chat request: "${queryDto.query}"`);
    return this.ragService.executeRagPipeline(queryDto);
  }

  @Get('health')
  @ApiOperation({
    summary: 'Health and Hardware Acceleration Status',
    description:
      'Returns the readiness of the LanceDB vector store, local LLM inference engine, and detailed GPU hardware acceleration status (NVIDIA CUDA / Apple Metal / CPU).',
  })
  @ApiResponse({
    status: HttpStatus.OK,
    description: 'Service health and hardware acceleration diagnostics.',
    type: HealthResponseDto,
  })
  getHealth(): HealthResponseDto {
    return {
      status: 'ok',
      service: 'scientific-rag-backend',
      timestamp: new Date().toISOString(),
      components: {
        vectorStore: this.vectorStoreService.isReady() ? 'ready' : 'connecting_or_fallback',
        llm: this.llmService.isReady() ? 'ready' : 'fallback',
        gpu: this.llmService.getGpuStatus(),
      },
    };
  }
}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe, Logger } from '@nestjs/common';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { AppModule } from './app.module';

async function bootstrap() {
  const logger = new Logger('Bootstrap');
  const app = await NestFactory.create(AppModule);

  // Global DTO Validation
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );

  // CORS for frontend
  const frontendOrigin = process.env.FRONTEND_ORIGIN || 'http://localhost:5173';
  app.enableCors({
    origin: [frontendOrigin, 'http://localhost:3000', 'http://127.0.0.1:5173'],
    methods: 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
    credentials: true,
  });

  // OpenAPI / Swagger Documentation
  const swaggerConfig = new DocumentBuilder()
    .setTitle('Scientific Literature RAG API')
    .setDescription(
      'Hardware-accelerated (NVIDIA CUDA / Apple Metal) Retrieval-Augmented Generation API over 913,205 scientific paper chunks with co-authorship PageRank hybrid reranking and local Qwen2.5-7B GGUF inference.',
    )
    .setVersion('1.0.0')
    .addTag('Scientific RAG', 'Endpoints for semantic literature search, graph reranking, and grounded LLM synthesis')
    .build();

  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('api/docs', app, document, {
    jsonDocumentUrl: 'api/docs-json',
    customSiteTitle: 'Scientific RAG Backend — OpenAPI Specification',
  });

  const port = process.env.GATEWAY_PORT || process.env.PORT || 8000;
  await app.listen(port);
  logger.log(`Scientific RAG Backend server listening on port ${port}`);
  logger.log(`Swagger UI Documentation: http://localhost:${port}/api/docs`);
  logger.log(`OpenAPI JSON Schema: http://localhost:${port}/api/docs-json`);
  logger.log(`Health endpoint: http://localhost:${port}/api/rag/health`);
  logger.log(`Chat endpoint: http://localhost:${port}/api/rag/chat`);
}
bootstrap();

