export interface GroundedChunkResult {
  chunk_id: string;
  paper_id: string;
  title: string;
  authors?: string[];
  primary_category?: string;
  section_title?: string;
  text: string;
  similarity_score: number;
  authority_score: number;
  final_score: number;
  citation_tag: string;
}

export interface RAGSynthesisResponse {
  query: string;
  answer: string;
  citations: string[];
  grounded_chunks: GroundedChunkResult[];
  latency_ms: number;
}

export interface GpuStatus {
  hasGpu: boolean;
  type: string;
  platform: string;
  arch: string;
  details: string;
  nodeLlamaGpuOption: string | boolean;
}

export interface HealthResponse {
  status: string;
  service: string;
  timestamp: string;
  components: {
    vectorStore: string;
    llm: string;
    gpu: GpuStatus | null;
  };
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  citations?: string[];
  grounded_chunks?: GroundedChunkResult[];
  latency_ms?: number;
}

export interface QueryOptions {
  top_k: number;
  category?: string;
  use_authority_boost: boolean;
  expand_query: boolean;
}

import { NextRequest, NextResponse } from 'next/server';

const BACKEND_URL = process.env.BACKEND_URL || 'http://localhost:8000';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();

    const response = await fetch(`${BACKEND_URL}/api/rag/chat`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      const errorText = await response.text();
      return NextResponse.json(
        { error: `Backend error: ${response.statusText}`, details: errorText },
        { status: response.status },
      );
    }

    const data = await response.json();
    return NextResponse.json(data);
  } catch (error) {
    return NextResponse.json(
      {
        error: 'Failed to communicate with RAG Backend',
        message: (error as Error).message,
        hint: 'Ensure NestJS backend is running on port 8000 (node dist/main.js)',
      },
      { status: 502 },
    );
  }
}

import { NextResponse } from 'next/server';

const BACKEND_URL = process.env.BACKEND_URL || 'http://localhost:8000';

export async function GET() {
  try {
    const response = await fetch(`${BACKEND_URL}/api/rag/health`, {
      cache: 'no-store',
    });

    if (!response.ok) {
      return NextResponse.json(
        { status: 'degraded', error: response.statusText },
        { status: response.status },
      );
    }

    const data = await response.json();
    return NextResponse.json(data);
  } catch (error) {
    return NextResponse.json(
      {
        status: 'offline',
        service: 'scientific-rag-backend',
        error: (error as Error).message,
        components: {
          vectorStore: 'unreachable',
          llm: 'unreachable',
          gpu: null,
        },
      },
      { status: 503 },
    );
  }
}

