        {/* Loading Indicator */}
        {isLoading && (
          <div className="flex gap-4 max-w-2xl mr-auto items-start">
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl bg-indigo-600/30 text-indigo-300 border border-indigo-500/40">
